var n=`0944-chicken-teriyaki`;var t=`world-0944`;var a=`JP`;var s=`east-asia`;var r=4;var o=64;var g={en:`Chicken Teriyaki`,ua:`Курка теріякі`};var h={en:`Chicken Teriyaki is a Japan dish made with chicken thigh, light soy sauce, white sesame seeds, green onion. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Курка теріякі, страва кухні країни Японія. Основні складники: куряче стегно, світлий соєвий соус, білий кунжут, зелена цибуля. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var d=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 35 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 35 хвилин.`,t:[`marinating`],m:35,i:[[`chicken-thigh`,780,`g`],[`light-soy-sauce`,75,`ml`],[`mirin`,70,`ml`],[`sake`,50,`ml`],[`ground-ginger`,15,`g`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 18 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 18 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:18,i:[[`canola-oil`,35,`ml`]]},{en:`Simmer the liquid and flavorings uncovered for about 8 minutes until reduced and concentrated.`,ua:`Уварюйте рідину з приправами без кришки приблизно 8 хвилин до насичення та загустіння.`,t:[`reducing-sauce`],m:8,i:[[`white-granulated-sugar`,25,`g`],[`water`,90,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`white-sesame-seeds`,16,`g`],[`green-onion`,45,`g`]]}];var u={slug:n,id:t,country:`JP`,region:s,servings:4,minutes:64,title:g,text:h,steps:d};export{a as country,u as default,t as id,o as minutes,s as region,r as servings,n as slug,d as steps,h as text,g as title};